-- Sentetik K09 kabul verisi; gerçek kişi/veri/sır içermez.
-- Parola hash işareti testte geçici bir Werkzeug hash ile değiştirilir.
CREATE TABLE oteller ( id integer NOT NULL, ad varchar NOT NULL, adres text, telefon varchar, email varchar, vergi_no varchar, aktif boolean, logo text, email_bildirim_aktif boolean, email_uyari_aktif boolean, email_rapor_aktif boolean, email_sistem_aktif boolean );
CREATE TABLE katlar ( id integer NOT NULL, otel_id integer NOT NULL, kat_adi varchar NOT NULL, kat_no integer NOT NULL, aktif boolean );
CREATE TABLE oda_tipleri ( id integer NOT NULL, ad varchar NOT NULL, aktif boolean, dolap_sayisi integer );
CREATE TABLE odalar ( id integer NOT NULL, kat_id integer, oda_no varchar NOT NULL, kapasite integer, aktif boolean, qr_kod_token varchar, qr_kod_gorsel text, qr_kod_olusturma_tarihi timestamp, misafir_mesaji varchar, oda_tipi_id integer );
CREATE TABLE urun_gruplari ( id integer NOT NULL, grup_adi varchar NOT NULL, aciklama text, aktif boolean );
CREATE TABLE urunler ( id integer NOT NULL, grup_id integer NOT NULL, urun_adi varchar NOT NULL, barkod varchar, birim varchar, kritik_stok_seviyesi integer, aktif boolean, urun_kodu varchar, satis_fiyati numeric, alis_fiyati numeric, kar_tutari numeric, kar_orani numeric );
CREATE TABLE setuplar ( id integer NOT NULL, ad varchar NOT NULL, aciklama varchar, aktif boolean, dolap_ici boolean );
CREATE TABLE setup_icerik ( id integer NOT NULL, setup_id integer NOT NULL, urun_id integer NOT NULL, adet integer NOT NULL );
CREATE TABLE oda_tipi_setup ( otel_id integer NOT NULL, oda_tipi_id integer NOT NULL, setup_id integer NOT NULL );
CREATE TABLE kullanicilar ( id integer NOT NULL, kullanici_adi varchar NOT NULL, sifre_hash varchar NOT NULL, ad varchar NOT NULL, soyad varchar NOT NULL, email varchar, telefon varchar, rol varchar NOT NULL, aktif boolean, olusturma_tarihi timestamp, son_giris timestamp, otel_id integer, depo_sorumlusu_id integer, tema_renk_1 varchar, tema_renk_2 varchar, email_bildirim_aktif boolean );
CREATE TABLE kullanici_otel ( id integer NOT NULL, kullanici_id integer NOT NULL, otel_id integer NOT NULL, olusturma_tarihi timestamp );
CREATE TABLE email_ayarlari ( id integer NOT NULL, smtp_server varchar NOT NULL, smtp_port integer NOT NULL, smtp_username varchar NOT NULL, smtp_password varchar NOT NULL, smtp_use_tls boolean, smtp_use_ssl boolean, sender_email varchar NOT NULL, sender_name varchar, aktif boolean, olusturma_tarihi timestamptz, guncelleme_tarihi timestamptz, guncelleyen_id integer );
CREATE TABLE email_loglari ( id integer NOT NULL, alici_email varchar NOT NULL, alici_kullanici_id integer, konu varchar NOT NULL, icerik text NOT NULL, email_tipi varchar NOT NULL, durum varchar, hata_mesaji text, gonderim_tarihi timestamptz, okundu boolean, okunma_tarihi timestamptz, tracking_id varchar, ilgili_tablo varchar, ilgili_kayit_id integer, ek_bilgiler jsonb );
CREATE TABLE kat_sorumlusu_siparis_talepleri ( id integer NOT NULL, talep_no varchar NOT NULL, kat_sorumlusu_id integer NOT NULL, depo_sorumlusu_id integer, talep_tarihi timestamptz NOT NULL, onay_tarihi timestamptz, teslim_tarihi timestamptz, durum varchar NOT NULL, aciklama text, red_nedeni text, olusturma_tarihi timestamptz NOT NULL, guncelleme_tarihi timestamptz );
CREATE TABLE kat_sorumlusu_siparis_talep_detaylari ( id integer NOT NULL, talep_id integer NOT NULL, urun_id integer NOT NULL, talep_miktari integer NOT NULL, onaylanan_miktar integer NOT NULL, teslim_edilen_miktar integer NOT NULL, aciliyet varchar NOT NULL, olusturma_tarihi timestamptz NOT NULL );
CREATE TABLE bildirimler ( id integer NOT NULL, hedef_rol varchar NOT NULL, hedef_otel_id integer, hedef_kullanici_id integer, bildirim_tipi varchar NOT NULL, baslik varchar NOT NULL, mesaj text, okundu boolean, olusturma_tarihi timestamptz, oda_id integer, gorev_id integer, gonderen_id integer );
CREATE TABLE minibar_dolum_talepleri ( id integer NOT NULL, oda_id integer NOT NULL, talep_tarihi timestamp NOT NULL, durum varchar NOT NULL, tamamlanma_tarihi timestamp, notlar text, tamamlayan_id integer, goren_id integer, gorulme_tarihi timestamptz, kapatma_aciklamasi text, iptal_aciklamasi text, iptal_eden_id integer, iptal_tarihi timestamptz );
CREATE TABLE minibar_dolum_talebi_detay ( id integer NOT NULL, talep_id integer NOT NULL, urun_id integer NOT NULL, olusturma_tarihi timestamptz );
CREATE TABLE minibar_islemleri ( id integer NOT NULL, oda_id integer NOT NULL, personel_id integer NOT NULL, islem_tipi varchar NOT NULL, islem_tarihi timestamp, aciklama text );
CREATE TABLE minibar_islem_detay ( id integer NOT NULL, islem_id integer NOT NULL, urun_id integer NOT NULL, baslangic_stok integer, bitis_stok integer, tuketim integer, eklenen_miktar integer, zimmet_detay_id integer, ekstra_miktar integer, satis_fiyati numeric, alis_fiyati numeric, kar_tutari numeric, kar_orani numeric, bedelsiz boolean, kampanya_id integer, setup_miktari integer );
CREATE TABLE oda_kontrol_kayitlari ( id integer NOT NULL, oda_id integer NOT NULL, personel_id integer NOT NULL, kontrol_tarihi date NOT NULL, baslangic_zamani timestamptz NOT NULL, bitis_zamani timestamptz, kontrol_tipi varchar NOT NULL, olusturma_tarihi timestamptz NOT NULL );
CREATE TABLE otel_zimmet_stok ( id integer NOT NULL, otel_id integer NOT NULL, urun_id integer NOT NULL, toplam_miktar integer NOT NULL, kullanilan_miktar integer NOT NULL, kalan_miktar integer NOT NULL, kritik_stok_seviyesi integer, son_guncelleme timestamptz, olusturma_tarihi timestamptz );
CREATE TABLE personel_zimmet ( id integer NOT NULL, personel_id integer NOT NULL, zimmet_tarihi timestamp, iade_tarihi timestamp, teslim_eden_id integer, durum varchar, aciklama text, otel_id integer );
CREATE TABLE personel_zimmet_detay ( id integer NOT NULL, zimmet_id integer NOT NULL, urun_id integer NOT NULL, miktar integer NOT NULL, kullanilan_miktar integer, kalan_miktar integer, iade_edilen_miktar integer, kritik_stok_seviyesi integer );
CREATE TABLE personel_zimmet_kullanim ( id integer NOT NULL, otel_zimmet_stok_id integer NOT NULL, personel_id integer NOT NULL, urun_id integer NOT NULL, kullanilan_miktar integer NOT NULL, islem_tarihi timestamptz, islem_tipi varchar, referans_islem_id integer, aciklama text, olusturan_id integer );
CREATE TABLE zimmet_sablonlari ( id integer NOT NULL, sablon_adi varchar NOT NULL, aciklama text, olusturan_id integer, otel_id integer, aktif boolean, olusturma_tarihi timestamptz, guncelleme_tarihi timestamptz );
CREATE TABLE zimmet_sablon_detaylari ( id integer NOT NULL, sablon_id integer NOT NULL, urun_id integer NOT NULL, varsayilan_miktar integer NOT NULL );
CREATE TABLE dosya_yuklemeleri ( id integer NOT NULL, islem_kodu varchar NOT NULL, dosya_adi varchar, dosya_tipi varchar NOT NULL, durum varchar, toplam_satir integer, basarili_satir integer, hatali_satir integer, hata_detaylari text, yukleme_tarihi timestamp, yukleyen_id integer, otel_id integer NOT NULL, dosya_yolu varchar, dosya_boyutu integer, silme_tarihi timestamp, yuklenen_kullanici_id integer );
CREATE TABLE misafir_kayitlari ( id integer NOT NULL, oda_id integer NOT NULL, islem_kodu varchar NOT NULL, misafir_sayisi integer, giris_tarihi date NOT NULL, giris_saati time, cikis_tarihi date NOT NULL, cikis_saati time, kayit_tipi varchar NOT NULL, olusturma_tarihi timestamp, olusturan_id integer, dosya_yukleme_id integer, kaynak varchar, durum varchar, otel_id integer, guncelleme_tarihi timestamp );
CREATE TABLE yukleme_gorevleri ( id integer NOT NULL, otel_id integer NOT NULL, depo_sorumlusu_id integer, gorev_tarihi date NOT NULL, dosya_tipi varchar NOT NULL, durum varchar, yukleme_zamani timestamptz, dosya_yukleme_id integer, olusturma_tarihi timestamptz );
CREATE TABLE gunluk_gorevler ( id integer NOT NULL, otel_id integer NOT NULL, personel_id integer, gorev_tarihi date NOT NULL, gorev_tipi varchar, durum varchar, olusturma_tarihi timestamptz, tamamlanma_tarihi timestamptz, notlar text );
CREATE TABLE gorev_detaylari ( id integer NOT NULL, gorev_id integer NOT NULL, oda_id integer NOT NULL, misafir_kayit_id integer, durum varchar, varis_saati time, cikis_saati time, oncelik_sirasi integer, kontrol_zamani timestamptz, dnd_sayisi integer, son_dnd_zamani timestamptz, notlar text );
CREATE TABLE gorev_durum_loglari ( id integer NOT NULL, gorev_detay_id integer NOT NULL, onceki_durum varchar, yeni_durum varchar, degisiklik_zamani timestamptz, degistiren_id integer, aciklama text );
CREATE TABLE oda_dnd_kayitlari ( id integer NOT NULL, oda_id integer NOT NULL, otel_id integer, kayit_tarihi date NOT NULL, dnd_sayisi integer, ilk_dnd_zamani timestamp, son_dnd_zamani timestamp, durum varchar, gorev_detay_id integer, olusturma_tarihi timestamp, guncelleme_tarihi timestamp );
CREATE TABLE oda_dnd_kontrolleri ( id integer NOT NULL, dnd_kayit_id integer NOT NULL, kontrol_no integer, kontrol_eden_id integer, kontrol_zamani timestamp NOT NULL, notlar text );
CREATE TABLE dnd_kontroller ( id integer NOT NULL, gorev_detay_id integer NOT NULL, kontrol_zamani timestamptz NOT NULL, kontrol_eden_id integer, notlar text );
CREATE TABLE qr_kod_okutma_loglari ( id integer NOT NULL, oda_id integer, kullanici_id integer, okutma_tarihi timestamp NOT NULL, okutma_tipi varchar NOT NULL, ip_adresi varchar, user_agent varchar, basarili boolean, hata_mesaji text );
CREATE TABLE audit_logs ( id integer NOT NULL, kullanici_id integer, kullanici_adi varchar, kullanici_rol varchar, islem_tipi varchar, tablo_adi varchar, kayit_id integer, eski_deger jsonb, yeni_deger jsonb, ip_adresi varchar, user_agent varchar, islem_tarihi timestamp NOT NULL );
CREATE TABLE sistem_loglari ( id integer NOT NULL, kullanici_id integer, islem_tipi varchar, modul varchar, islem_detay jsonb, ip_adresi varchar, tarayici varchar, islem_tarihi timestamp NOT NULL );

